    missions?: any[]; // Simplified for now
}

export const TimesheetsView: React.FC<TimesheetsViewProps> = ({ timesheets, onUpdateStatus, missions = [] }) => {
    const { t } = useTranslation();
    const [selectedTimesheet, setSelectedTimesheet] = React.useState<Timesheet | null>(null);
