    // Mock active mission list for entry mode
    const activeMissions = missions.filter((m: any) => m.status === 'Active');

    const getStatusBadge = (status: TimesheetStatus) => {
        const styles = {
            'Draft': 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300',
            'Submitted': 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300',
            'Validated': 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
            'Rejected': 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300',
        };
        return <span className={`px-2 py-1 rounded-full text-xs font-bold uppercase ${styles[status]}`}>{status}</span>;
    };

