                { date: '2023-11-03', hours: 8, type: 'Production' },
                { date: '2023-11-04', hours: 8, type: 'Production' },
                { date: '2023-11-05', hours: 8, type: 'Production' },
            ]
        };
        // In a real app, we would add this to the parent state via a prop
        // onUpdateStatus is currently only for status, we'd need onCreate
        alert("Timesheet creation UI would open here. (Simulated)");
    };

    const exportToCsv = () => {
        if (!window.XLSX) return;
        const data = timesheets.flatMap(ts => ts.days.map(d => ({
            Consultant: ts.consultantName,
            Client: ts.clientName,
            Date: d.date,
            Heures: d.hours,
            Type: d.type,
            Note: d.note || ''
        })));
        const ws = window.XLSX.utils.json_to_sheet(data);
        const wb = window.XLSX.utils.book_new();
        window.XLSX.utils.book_append_sheet(wb, ws, "Timesheets");
        window.XLSX.writeFile(wb, `ParseLIQ_Timesheets.xlsx`);
