             showToast(t('toast.files_added'), 'success');
        }

        setCvFiles([...currentFiles, ...newOtherCvFiles]);

        if (isDummyDataActive && (wasUpdatedFromJson || newOtherCvFiles.length > 0 || jsonFiles.length > 0)) {
            setIsDummyDataActive(false);
